// ==========================================================
// Extract and validate incoming WhatsApp message
// Supports Evolution API v2 webhook format
// ==========================================================
const body = $input.first().json.body || $input.first().json;

// Evolution API v2 sends data in body.data
const data = body.data || body;
const messageData = data.message || data;

// Extract key fields
const remoteJid = data.key?.remoteJid || data.remoteJid || '';
const fromMe = data.key?.fromMe || false;
const pushName = data.pushName || data.senderName || 'Usuario';
const messageId = data.key?.id || data.messageId || '';

// Skip messages sent by the bot itself
if (fromMe) {
  return [{ json: { skip: true, reason: 'own_message' } }];
}

// Skip non-user messages (group, status, etc.)
if (!remoteJid.endsWith('@s.whatsapp.net')) {
  return [{ json: { skip: true, reason: 'not_personal_chat' } }];
}

// Extract text from different message types
let messageText = '';
if (messageData.conversation) {
  messageText = messageData.conversation;
} else if (messageData.extendedTextMessage?.text) {
  messageText = messageData.extendedTextMessage.text;
} else if (messageData.buttonsResponseMessage?.selectedDisplayText) {
  messageText = messageData.buttonsResponseMessage.selectedDisplayText;
} else if (messageData.listResponseMessage?.title) {
  messageText = messageData.listResponseMessage.title;
} else {
  // Unsupported message type (audio, image, etc.)
  return [{ json: {
    skip: false,
    unsupported: true,
    chatId: remoteJid,
    phoneNumber: remoteJid.replace('@s.whatsapp.net', ''),
    pushName: pushName
  } }];
}

// Clean and trim the message
messageText = messageText.trim();
if (!messageText) {
  return [{ json: { skip: true, reason: 'empty_message' } }];
}

return [{ json: {
  skip: false,
  unsupported: false,
  chatId: remoteJid,
  phoneNumber: remoteJid.replace('@s.whatsapp.net', ''),
  pushName: pushName,
  messageText: messageText,
  messageId: messageId,
  timestamp: new Date().toISOString()
} }];

