// ==========================================================
// Check user authentication state
// ==========================================================
const items = $input.all();
const userData = items.length > 0 ? items[0].json : null;
const chatId = $('Extract Message').item.json.chatId;
const phoneNumber = $('Extract Message').item.json.phoneNumber;
const messageText = $('Extract Message').item.json.messageText;
const pushName = $('Extract Message').item.json.pushName;

if (!userData || !userData.chat_id) {
  // New user — not registered yet
  return [{ json: {
    authenticated: false,
    isNewUser: true,
    chatId: chatId,
    phoneNumber: phoneNumber,
    messageText: messageText,
    pushName: pushName
  } }];
}

if (userData.state !== 'active' || !userData.refresh_token) {
  // Registered but not yet authorized with Google
  return [{ json: {
    authenticated: false,
    isNewUser: false,
    chatId: chatId,
    phoneNumber: phoneNumber,
    messageText: messageText,
    pushName: pushName
  } }];
}

// Check if access token is expired
const tokenExpiry = new Date(userData.token_expiry);
const now = new Date();
const isExpired = now >= tokenExpiry;

return [{ json: {
  authenticated: true,
  isNewUser: false,
  chatId: chatId,
  phoneNumber: phoneNumber,
  messageText: messageText,
  pushName: pushName,
  accessToken: userData.access_token,
  refreshToken: userData.refresh_token,
  tokenExpiry: userData.token_expiry,
  tokenExpired: isExpired,
  timezone: userData.timezone || 'America/Argentina/Buenos_Aires',
  pendingAction: userData.pending_action || '',
  pendingData: userData.pending_data || '',
  lastAiResponse: userData.last_ai_response || '',
  turnCount: parseInt(userData.turn_count || '0', 10)
} }];

// ==========================================================
// Handle unauthenticated users
// Register new users and send OAuth link
// ==========================================================
const chatId = $json.chatId;
const phoneNumber = $json.phoneNumber;
const pushName = $json.pushName;

// Build the OAuth URL
const clientId = $env.GOOGLE_CLIENT_ID;
const redirectUri = encodeURIComponent(`${$env.N8N_BASE_URL}/webhook/google-oauth-callback`);
const state = Buffer.from(chatId).toString('base64');
const scope = encodeURIComponent('https://www.googleapis.com/auth/calendar https://www.googleapis.com/auth/calendar.events');

const oauthUrl = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${clientId}&redirect_uri=${redirectUri}&response_type=code&scope=${scope}&access_type=offline&prompt=consent&state=${state}`;

return [{ json: {
  chatId: chatId,
  phoneNumber: phoneNumber,
  pushName: pushName,
  isNewUser: $json.isNewUser,
  oauthUrl: oauthUrl
} }];

