// ==========================================================
// Process refreshed token and update context
// ==========================================================
const response = $input.first().json;
const prevData = $('Check User Auth').item.json;

let accessToken = prevData.accessToken;
let tokenExpiry = prevData.tokenExpiry;

if (response.body?.access_token || response.access_token) {
  const body = response.body || response;
  accessToken = body.access_token;
  const expiresIn = body.expires_in || 3600;
  tokenExpiry = new Date(Date.now() + (expiresIn * 1000)).toISOString();
}

return [{ json: {
  ...prevData,
  accessToken: accessToken,
  tokenExpiry: tokenExpiry,
  tokenExpired: false
} }];

// ==========================================================
// Build the AI Context for OpenAI
// Replaces all placeholders in the system prompt
// ==========================================================
const data = $input.first().json;
const timezone = data.timezone || 'America/Argentina/Buenos_Aires';

// Calculate current date/time in user's timezone
const now = new Date();
const dateOptions = { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false };
const currentDatetime = now.toLocaleString('es-AR', dateOptions);

const dayNames = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
// Get day of week in the user's timezone
const dayFormatter = new Intl.DateTimeFormat('es-AR', { timeZone: timezone, weekday: 'long' });
const currentDayOfWeek = dayFormatter.format(now);

// Current ISO datetime with timezone offset for Argentina (-03:00)
const isoNow = now.toISOString().replace('Z', '-03:00');

// Build system message
let systemMessage = `Sos un asistente de calendario inteligente que habla en español rioplatense (argentino).
Tu trabajo es interpretar mensajes de usuarios de WhatsApp y extraer la intención
relacionada con Google Calendar.

Respondés de forma amigable, concisa y natural — como un asistente personal real,
no como un bot técnico. Usás "vos" en lugar de "tú".

## FECHA Y HORA ACTUAL
Zona horaria del usuario: ${timezone}
Fecha y hora actual: ${currentDatetime}
Día de la semana actual: ${currentDayOfWeek}
Fecha ISO actual: ${isoNow}`;

// Add pending action context if exists
if (data.pendingAction && data.pendingAction.trim() !== '') {
  systemMessage += `

## CONTEXTO DE CONVERSACIÓN (continuación)
ATENCIÓN: Hay una acción pendiente de turnos anteriores:
- Acción: ${data.pendingAction}
- Datos acumulados: ${data.pendingData}
- Última respuesta del bot: ${data.lastAiResponse}
- Turnos en esta conversación: ${data.turnCount}

El usuario está respondiendo a una pregunta anterior. Integrá su respuesta
con los datos pendientes para completar la acción.`;
}

// Add interpretation rules
systemMessage += `

## REGLAS DE INTERPRETACIÓN

1. INTENTS DISPONIBLES:
   - CREATE: El usuario quiere crear/agendar/programar un evento nuevo
   - QUERY: El usuario quiere saber qué eventos tiene (hoy, mañana, esta semana, etc.)
   - UPDATE: El usuario quiere modificar/cambiar/mover un evento existente
   - DELETE: El usuario quiere borrar/cancelar/eliminar un evento existente
   - GENERAL: Saludo, pregunta sobre el bot, tema no relacionado con calendario, agradecimiento

2. CAMPOS PARA EVENTOS:
   - summary (obligatorio para CREATE): Título/nombre del evento
   - start_datetime (obligatorio para CREATE): Formato ISO 8601 con offset de timezone
   - end_datetime (obligatorio para CREATE): Si no se especifica duración, asumir 1 hora
   - description (opcional): Detalles adicionales del evento
   - location (opcional): Lugar del evento

3. INTERPRETACIÓN DE FECHAS RELATIVAS (basándote en la fecha/hora actual):
   - "mañana" = fecha actual + 1 día
   - "pasado mañana" = fecha actual + 2 días
   - "el lunes", "el martes", etc. = próximo día con ese nombre
   - "la semana que viene" = lunes de la próxima semana
   - "a la mañana" = 09:00 si no hay hora específica
   - "al mediodía" = 12:00
   - "a la tarde" = 14:00 si no hay hora específica
   - "a la noche" = 20:00 si no hay hora específica
   - "en una hora" = hora actual + 1 hora
   - "ahora" / "ya" = hora actual redondeada a los próximos 15 minutos

4. CAMPOS OBLIGATORIOS POR INTENT:
   - CREATE: summary + start_datetime (end_datetime se puede inferir como +1 hora)
   - QUERY: al menos un rango de tiempo (si dice "mis eventos" sin fecha, asumir "hoy")
   - UPDATE: search_query para identificar el evento + al menos un campo a modificar
   - DELETE: search_query para identificar el evento a borrar

5. MULTI-TURN (conversación de varios pasos):
   - Si faltan campos obligatorios, listá los campos faltantes en missing_fields
   - Generá una pregunta natural y amigable en response_if_incomplete
   - Máximo 3 preguntas de seguimiento
   - Si el usuario dice "cancelar", "dejá", "no importa", "olvidate" → devolvé intent GENERAL con cancel_pending: true

6. CAMBIO DE TEMA:
   - Si detectás que el usuario cambió completamente de tema respecto a pending_action,
     ignorá el pending_action y procesá el nuevo intent desde cero

7. BÚSQUEDA DE EVENTOS (para UPDATE/DELETE):
   - El campo search_query debe contener palabras clave para buscar el evento
   - Incluí título parcial, nombres de personas, o contexto temporal

8. FORMATO DE RESPUESTAS:
   - Usá emojis con moderación (✅, 📅, ✏️, 🗑️, 📋)
   - Sé conciso pero informativo
   - Confirmá siempre los datos antes de ejecutar
   - Para QUERY: no generés response_text, el sistema lo genera con los eventos reales`;

// Add strict JSON format
systemMessage += `

## FORMATO DE RESPUESTA (JSON estricto, sin comentarios, sin texto adicional)

{
  "intent": "CREATE|UPDATE|DELETE|QUERY|GENERAL",
  "summary": "string o null",
  "start_datetime": "string ISO 8601 con timezone o null",
  "end_datetime": "string ISO 8601 con timezone o null",
  "description": "string o null",
  "location": "string o null",
  "missing_fields": ["array de nombres de campos obligatorios faltantes"],
  "response_if_incomplete": "string - pregunta natural al usuario si faltan campos, o null",
  "search_query": "string - palabras clave para buscar evento existente (UPDATE/DELETE), o null",
  "query_time_min": "string ISO 8601 - inicio del rango para QUERY, o null",
  "query_time_max": "string ISO 8601 - fin del rango para QUERY, o null",
  "response_text": "string - respuesta al usuario para GENERAL, o confirmación para CREATE/UPDATE/DELETE, o null",
  "cancel_pending": false
}`;

return [{ json: {
  ...data,
  systemMessage: systemMessage,
  userMessage: data.messageText
} }];

// ==========================================================
// Parse OpenAI response and route by intent
// ==========================================================
const prevData = $('Build AI Context').item.json;
const response = $input.first().json;

// Handle API errors
if (response.error || !response.choices?.[0]?.message?.content) {
  return [{ json: {
    ...prevData,
    intent: 'ERROR',
    responseText: 'Perdón, tuve un problema procesando tu mensaje. ¿Podés intentar de nuevo? 🙏',
    aiResponse: null
  } }];
}

// Parse the JSON response from OpenAI
let aiResponse;
try {
  aiResponse = JSON.parse(response.choices[0].message.content);
} catch (e) {
  return [{ json: {
    ...prevData,
    intent: 'ERROR',
    responseText: 'Perdón, no pude entender la respuesta. ¿Podés reformular tu mensaje? 🤔',
    aiResponse: null
  } }];
}

return [{ json: {
  ...prevData,
  intent: aiResponse.intent || 'GENERAL',
  summary: aiResponse.summary,
  startDatetime: aiResponse.start_datetime,
  endDatetime: aiResponse.end_datetime,
  description: aiResponse.description,
  location: aiResponse.location,
  missingFields: aiResponse.missing_fields || [],
  responseIfIncomplete: aiResponse.response_if_incomplete,
  searchQuery: aiResponse.search_query,
  queryTimeMin: aiResponse.query_time_min,
  queryTimeMax: aiResponse.query_time_max,
  responseText: aiResponse.response_text,
  cancelPending: aiResponse.cancel_pending || false,
  aiResponse: aiResponse
} }];

// ==========================================================
// Handle CREATE intent
// If missing_fields → multi-turn, else → create event
// ==========================================================
const data = $input.first().json;

if (data.missingFields && data.missingFields.length > 0) {
  // Incomplete — need more info
  return [{ json: {
    ...data,
    action: 'ask_more_info',
    replyText: data.responseIfIncomplete || '¿Podés darme más detalles para agendar el evento?'
  } }];
}

// Complete — ready to create event in Google Calendar
return [{ json: {
  ...data,
  action: 'create_event',
  replyText: data.responseText || '✅ Evento agendado.'
} }];

// ==========================================================
// Format query results into WhatsApp-friendly text
// ==========================================================
const prevData = $('Parse AI Response').item.json;
const response = $input.first().json;

if (response.error || !response.items) {
  return [{ json: {
    ...prevData,
    action: 'reply',
    replyText: 'Perdón, no pude consultar tu calendario. ¿Podés intentar de nuevo? 🙏'
  } }];
}

const events = response.items || [];

if (events.length === 0) {
  return [{ json: {
    ...prevData,
    action: 'reply',
    replyText: '📋 No tenés eventos agendados en ese período. ¡Calendario libre! 🎉'
  } }];
}

// Format events into a readable list
const timezone = prevData.timezone || 'America/Argentina/Buenos_Aires';
const timeOpts = { timeZone: timezone, hour: '2-digit', minute: '2-digit', hour12: false };
const dateOpts = { timeZone: timezone, weekday: 'short', day: 'numeric', month: 'short' };

let eventList = events.map((event, i) => {
  const start = event.start?.dateTime ? new Date(event.start.dateTime) : null;
  const end = event.end?.dateTime ? new Date(event.end.dateTime) : null;
  const title = event.summary || 'Sin título';

  if (start) {
    const timeStr = start.toLocaleTimeString('es-AR', timeOpts);
    const endStr = end ? end.toLocaleTimeString('es-AR', timeOpts) : '';
    const dateStr = start.toLocaleDateString('es-AR', dateOpts);
    return `${i + 1}. 📅 *${title}*\n   ${dateStr} — ${timeStr}${endStr ? ' a ' + endStr : ''}`;
  } else {
    // All-day event
    return `${i + 1}. 📅 *${title}* (todo el día)`;
  }
}).join('\n\n');

const header = events.length === 1 ? 'Tenés *1 evento*:' : `Tenés *${events.length} eventos*:`;

return [{ json: {
  ...prevData,
  action: 'reply',
  replyText: `📋 ${header}\n\n${eventList}`
} }];

// ==========================================================
// Handle UPDATE intent
// Search for the event, then update it
// ==========================================================
const data = $input.first().json;

if (data.missingFields && data.missingFields.length > 0) {
  return [{ json: {
    ...data,
    action: 'ask_more_info',
    replyText: data.responseIfIncomplete || '¿Qué evento querés modificar y cómo?'
  } }];
}

return [{ json: {
  ...data,
  action: 'update_event',
  replyText: data.responseText || '✏️ Evento actualizado.'
} }];

// ==========================================================
// Update the found event
// ==========================================================
const prevData = $('Handle UPDATE').item.json;
const response = $input.first().json;

if (response.error || !response.items || response.items.length === 0) {
  return [{ json: {
    ...prevData,
    action: 'reply',
    replyText: '🤔 No encontré el evento que querés modificar. ¿Podés darme más detalles?'
  } }];
}

// Take the first matching event
const event = response.items[0];
const eventId = event.id;

// Build update body with only changed fields
const updateBody = {};
if (prevData.summary) updateBody.summary = prevData.summary;
if (prevData.description) updateBody.description = prevData.description;
if (prevData.location) updateBody.location = prevData.location;
if (prevData.startDatetime) {
  updateBody.start = { dateTime: prevData.startDatetime, timeZone: prevData.timezone };
}
if (prevData.endDatetime) {
  updateBody.end = { dateTime: prevData.endDatetime, timeZone: prevData.timezone };
}

return [{ json: {
  ...prevData,
  eventId: eventId,
  eventTitle: event.summary,
  updateBody: updateBody,
  replyText: prevData.replyText
} }];

// ==========================================================
// Handle DELETE intent
// ==========================================================
const data = $input.first().json;

if (data.missingFields && data.missingFields.length > 0) {
  return [{ json: {
    ...data,
    action: 'ask_more_info',
    replyText: data.responseIfIncomplete || '¿Qué evento querés eliminar?'
  } }];
}

return [{ json: {
  ...data,
  action: 'delete_event',
  replyText: data.responseText || '🗑️ Evento eliminado.'
} }];

// ==========================================================
// Delete the found event
// ==========================================================
const prevData = $('Handle DELETE').item.json;
const response = $input.first().json;

if (response.error || !response.items || response.items.length === 0) {
  return [{ json: {
    ...prevData,
    action: 'reply',
    replyText: '🤔 No encontré el evento que querés eliminar. ¿Podés darme más detalles?'
  } }];
}

const event = response.items[0];

return [{ json: {
  ...prevData,
  eventId: event.id,
  eventTitle: event.summary,
  replyText: prevData.replyText
} }];

// ==========================================================
// Handle GENERAL intent and errors
// ==========================================================
const data = $input.first().json;

return [{ json: {
  ...data,
  action: 'reply',
  replyText: data.responseText || 'Hola 👋 ¿En qué te puedo ayudar con tu calendario?'
} }];

// ==========================================================
// Merge all branches and prepare final reply
// ==========================================================
const data = $input.first().json;

const chatId = data.chatId;
const phoneNumber = data.phoneNumber;
const intent = data.intent || 'GENERAL';
const replyText = data.replyText || data.responseText || 'Perdón, no pude procesar tu mensaje. 🙏';
const action = data.action || 'reply';

// Determine if we need to save pending state
let newPendingAction = '';
let newPendingData = '';
let newLastAiResponse = '';
let newTurnCount = 0;

if (action === 'ask_more_info') {
  // Multi-turn: save state for next message
  newPendingAction = intent;
  const pendingFields = {};
  if (data.summary) pendingFields.summary = data.summary;
  if (data.startDatetime) pendingFields.start_datetime = data.startDatetime;
  if (data.endDatetime) pendingFields.end_datetime = data.endDatetime;
  if (data.description) pendingFields.description = data.description;
  if (data.location) pendingFields.location = data.location;
  if (data.searchQuery) pendingFields.search_query = data.searchQuery;
  newPendingData = JSON.stringify(pendingFields);
  newLastAiResponse = replyText;
  newTurnCount = (data.turnCount || 0) + 1;
} else if (data.cancelPending) {
  // User cancelled pending action - clear state
  newPendingAction = '';
  newPendingData = '';
  newLastAiResponse = '';
  newTurnCount = 0;
}

return [{ json: {
  chatId: chatId,
  phoneNumber: phoneNumber,
  replyText: replyText,
  intent: intent,
  action: action,
  newPendingAction: newPendingAction,
  newPendingData: newPendingData,
  newLastAiResponse: newLastAiResponse,
  newTurnCount: newTurnCount
} }];
